node.interaction_0_script_to_run_on_interacti:
function OnInteraction(so_self, so_activator)
{
	local materials = Stage_QueryStageObjectsWithTag(STAGE_OBJECT_TYPE_ACTOR, "MATERIAL");
	if (materials)
	{
		foreach (material in materials)
		{
			local material_id = StageObject_GetKeyValue(material, "material_id");
			if (material_id == "TOMB_ORB")
			{
				Game_AddActorNotification(so_activator, LOC_TEXT("I should pick up that [MATERIAL_ICON=TOMB_ORB][MATERIAL_NAME=TOMB_ORB] before I leave!"));
				Game_AddActorNotification(so_activator, LOC_TEXT("Press [BUTTON=DROP] to open the Carried Materials menu."));
				return;
			}
		}
	}

	Game_SetStagePointOfInterestCompleted(so_self);

	local pos = StageObject_GetPosition(so_self);
	local angle = StageObject_GetAngle(so_self);
	Actor_QueueActionMove(so_activator, pos[0], pos[1]);
	Actor_QueueActionTurn(so_activator, angle);
	Actor_QueueActionPlayAnimation(so_activator, "tool_unequip", true);
	Actor_QueueActionSendCommandWord(so_activator, so_self, "wait");
	Actor_QueueActionPlayAnimation(so_activator, "exit_tomb", false);

	Actor_QueueActionWaitForCommandWord(so_self, "wait");
	Actor_QueueActionPlayAnimation(so_self, "exit_tomb", true);

	Game_SetCinemaMode(true);
	local travel_to_entrance_id = StageObject_GetKeyValue(so_self, "travel_to_entrance_id");
	if (travel_to_entrance_id == null || travel_to_entrance_id == "")
	{
		// Fallback for returning from tombs etc.
		Game_SetScreenFadeOutWithCommand(3, "travel_back_from_stage", so_activator, 2);
	}
	else
	{
		Game_SetScreenFadeOutWithCommand(3, "travel_to_stage", so_self, 2);
	}
}

node.interaction_1_script_to_run_on_interacti:
function OnInteraction(so_self, so_activator)
{
	Game_SetStagePointOfInterestCompleted(so_self);

	local pos = StageObject_GetPosition(so_self);

	local player_index = Game_GetPlayerIndexByActor(so_activator);
	StageObject_SetPosition(so_activator, pos[0] + 60 * player_index, pos[1] + 20, pos[2]);
	StageObject_SetAngle(so_activator, 40 * player_index);
	Actor_PlayAnimationWithDelayPlaybackSpeedAndPosition(so_activator, "enter_tomb_inside", 0, 1 + 0.15*player_index, 0.1 * player_index);
}
